<?php
namespace App\Http\Controllers;
use App\Models\Province; use App\Models\City; use App\Models\Location;
class DirectoryController extends Controller { public function home(){ $provinces=Province::withCount('cities')->orderBy('name')->get(); return view('directory.home',compact('provinces')); } public function province(string $province){ $province=Province::with(['cities'=>fn($q)=>$q->withCount(['carpetCleanings','locations'])->orderBy('name')])->where('slug',$province)->firstOrFail(); return view('directory.province',compact('province')); } public function city(string $city){ $city=City::with(['province','locations'=>fn($q)=>$q->withCount('carpetCleanings')->orderBy('name'),'carpetCleanings'=>fn($q)=>$q->where('is_active',true)->orderBy('name')])->where('slug',$city)->firstOrFail(); return view('directory.city',compact('city')); } public function location(string $city,string $location){ $city=City::with('province')->where('slug',$city)->firstOrFail(); $location=Location::with(['carpetCleanings'=>fn($q)=>$q->where('is_active',true)->orderBy('name')])->where('city_id',$city->id)->where('slug',$location)->firstOrFail(); return view('directory.location',compact('city','location')); } }